import{_ as o,l as n,o as e,c as l,v as t,p as s,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"可用安全","description":"","frontmatter":{"title":"可用安全","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/usable-security.md","filePath":"cs/usable-security.md","lastUpdated":1789023840000}'),p={name:"cs/usable-security.md"};function E(u,a,_,A,m,B){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="可用安全" tabindex="-1">可用安全 <a class="header-anchor" href="#可用安全" aria-label="Permalink to &quot;可用安全&quot;">​</a></h1><div class="epigraph"><p>用户会绕过使他们无法完成工作的控制。Whitten 与 Tygar 表明：密码学 UI 失败则密钥管理失败。安全必须是默认且可完成的任务，而不是考试。</p><footer>—— Whitten and Tygar, Why Johnny Can&#39;t Encrypt, USENIX Security 1999；对照 Anderson 对操作</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/security-economics">安全经济学</a>是组织激励。缺口是<strong>个人操作</strong>：警告疲劳、证书对话框、MFA 摩擦。本课可用安全。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>点击「继续」绕过证书错误，链验证课白做。缺口是：默认安全路径、清晰失败、减少警告。</p><h3 id="钓鱼" tabindex="-1">钓鱼 <a class="header-anchor" href="#钓鱼" aria-label="Permalink to &quot;钓鱼&quot;">​</a></h3><p>可用不等于无钓鱼。WebAuthn 绑 origin 是设计，不是再教育用户看 URL。</p><p><span class="marginnote">Johnny 1999。风险量化下一课试图给决策数字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照警告疲劳。设计：安全默认、少问。下一课风险量化。</p>',12)),(e(),s(c,null,{default:r(()=>[h(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TASK%5B%22%E7%94%A8%E6%88%B7%E8%A6%81%E5%AE%8C%E6%88%90%E7%9A%84%E5%B7%A5%E4%BD%9C%22%5D%20--%3E%20CTRL%5B%22%E6%8E%A7%E5%88%B6%22%5D%0A%20%20CTRL%20--%3E%20BYPASS%5B%22%E8%BF%87%E9%9A%BE%E5%88%99%E7%BB%95%E8%BF%87%22%5D%0A%20%20DEF%5B%22%E5%AE%89%E5%85%A8%E9%BB%98%E8%AE%A4%22%5D%20--%3E%20DONE%5B%22%E4%BB%8D%E8%83%BD%E5%AE%8C%E6%88%90%E4%BB%BB%E5%8A%A1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>人是系统一部分。量化下一课给管理层优先级，仍要可用。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不嘲笑用户。风险量化下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>激励之后，个人会绕过难用的控制。</li><li>Johnny：加密 UI 失败即密钥失败。</li><li>安全默认优于更多对话框。</li><li>下一课风险量化。</li><li>出处：Whitten and Tygar, 1999；Anderson。</li></ul>',8))])}const T=o(p,[["render",E]]);export{f as __pageData,T as default};
